const lessons=[{"sentences":[{"speaker":"A","text":"Welcome to quick fix electronics where we repair your broken gadgets in less than one hour.","position":1,"audioStartSeconds":0,"audioEndSeconds":5.752416666666667},{"speaker":"A","text":"If your smartphone screen is cracked or your laptop battery dies quickly bring it to our central shop today.","position":2,"audioStartSeconds":5.952416666666666,"audioEndSeconds":12.42225},{"speaker":"A","text":"We offer free diagnostic checks because we want you to know the exact cost before any work starts.","position":3,"audioStartSeconds":12.62225,"audioEndSeconds":19.065583333333333},{"speaker":"A","text":"Although other repair stores charge high fees for urgent service our team keeps prices affordable for everyone.","position":4,"audioStartSeconds":19.265583333333332,"audioEndSeconds":25.953708333333335},{"speaker":"A","text":"Visit our website right now to book an appointment and get a ten percent discount on your first repair.","position":5,"audioStartSeconds":26.153708333333334,"audioEndSeconds":32.35216666666667},{"speaker":"A","text":"Do not let a damaged device slow down your daily routine when professional help is so close.","position":6,"audioStartSeconds":32.552166666666665,"audioEndSeconds":38.467125},{"speaker":"A","text":"Thank you for choosing our dependable local business for all your technology needs.","position":7,"audioStartSeconds":38.667125,"audioEndSeconds":43.770208333333336},{"speaker":"A","text":"Are you interested in learning new professional skills after working hours to improve your career prospects.","role":"section-start","position":8,"audioStartSeconds":48.770208333333336,"audioEndSeconds":55.097541666666665},{"speaker":"A","text":"Our community college opens registration for evening classes in digital marketing and web design starting next month.","position":9,"audioStartSeconds":55.29754166666667,"audioEndSeconds":62.642875},{"speaker":"A","text":"When students complete the twelve week program they receive an official certificate recognized by local employers.","position":10,"audioStartSeconds":62.842875,"audioEndSeconds":69.68566666666666},{"speaker":"A","text":"Because seats fill up very fast every semester you should register online before this coming friday.","position":11,"audioStartSeconds":69.88566666666667,"audioEndSeconds":76.16141666666667},{"speaker":"A","text":"Classes take place on tuesday and thursday evenings from seven until nine in the main building.","position":12,"audioStartSeconds":76.36141666666667,"audioEndSeconds":82.18616666666667},{"speaker":"A","text":"Call our main office if you need more information about tuition fees or payment plans.","position":13,"audioStartSeconds":82.38616666666667,"audioEndSeconds":87.875875},{"speaker":"A","text":"Do not miss this wonderful opportunity to invest in your future education and personal growth.","position":14,"audioStartSeconds":88.075875,"audioEndSeconds":94.02941666666666}],"questions":[{"prompt":"What is the main service offered by the first business?","options":["Selling new computers.","Repairing electronic devices.","Teaching digital marketing."],"answer":"B","evidenceSentence":1,"evidence":"we repair your broken gadgets in less than one hour","explanation":"Câu đầu tiên nêu rõ dịch vụ là sửa chữa các thiết bị điện tử bị hỏng."},{"prompt":"What does the first shop provide for free?","options":["Diagnostic checks.","Replacement batteries.","Online appointments."],"answer":"A","evidenceSentence":3,"evidence":"We offer free diagnostic checks","explanation":"Cửa hàng cung cấp các bài kiểm tra chẩn đoán miễn phí trước khi bắt đầu công việc."},{"prompt":"What incentive do customers get for booking online through the website?","options":["A free phone case.","A ten percent discount.","Faster repair service."],"answer":"B","evidenceSentence":5,"evidence":"get a ten percent discount on your first repair","explanation":"Khách hàng nhận được giảm giá mười phần trăm cho lần sửa chữa đầu tiên khi đặt lịch qua trang web."},{"prompt":"What kind of program is discussed in the second announcement?","options":["Evening classes.","Morning exercise.","Weekend cooking."],"answer":"A","evidenceSentence":9,"evidence":"registration for evening classes in digital marketing","explanation":"Thông báo thứ hai giới thiệu các lớp học buổi tối về tiếp thị kỹ thuật số và thiết kế web."},{"prompt":"When should students complete their registration according to the speaker?","options":["Before this coming Friday.","By the end of next month.","On Tuesday evening."],"answer":"A","evidenceSentence":11,"evidence":"you should register online before this coming friday","explanation":"Người nói khuyên học viên nên đăng ký trực tuyến trước thứ Sáu tuần này vì chỗ ngồi hết rất nhanh."},{"prompt":"What are students advised to do if they need payment information?","options":["Visit the main building.","Call the main office.","Send an email message."],"answer":"B","evidenceSentence":13,"evidence":"Call our main office if you need more information","explanation":"Học viên được khuyên gọi điện đến văn phòng chính nếu cần thêm thông tin về học phí."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
